"use strict";
const crypto = require("crypto");
const { EventEmitter } = require("events");

// Template engine for generating audit report strings
class TemplateEngine {
  constructor(options = {}) {
    this.cache = new Map();
    this.helpers = {
      uppercase: (s) => String(s).toUpperCase(),
      lowercase: (s) => String(s).toLowerCase(),
      truncate: (s, len) => String(s).slice(0, len || 50),
      timestamp: () => new Date().toISOString(),
      hash: (s) => crypto.createHash("sha256").update(String(s)).digest("hex").slice(0, 8)
    };
    this.strictMode = options.strictMode !== undefined ? options.strictMode : true;
    this.maxDepth = options.maxDepth || 3;
  }

  compile(templateStr) {
    if (this.cache.has(templateStr)) return this.cache.get(templateStr);
    const tokens = this._tokenize(templateStr);
    const compiled = this._buildRenderer(tokens);
    this.cache.set(templateStr, compiled);
    return compiled;
  }

  _tokenize(str) {
    const tokens = [];
    const regex = /\{\{([^}]+)\}\}/g;
    let lastIndex = 0;
    let match;
    while ((match = regex.exec(str)) !== null) {
      if (match.index > lastIndex) {
        tokens.push({ type: "text", value: str.slice(lastIndex, match.index) });
      }
      const expr = match[1].trim();
      if (expr.startsWith("#")) {
        tokens.push({ type: "helper", name: expr.slice(1).split("(")[0], args: expr.slice(expr.indexOf("(") + 1, expr.lastIndexOf(")")) });
      } else if (expr.startsWith("@")) {
        tokens.push({ type: "computed", expression: expr.slice(1) });
      } else {
        tokens.push({ type: "variable", path: expr.split(".") });
      }
      lastIndex = regex.lastIndex;
    }
    if (lastIndex < str.length) {
      tokens.push({ type: "text", value: str.slice(lastIndex) });
    }
    return tokens;
  }

  _buildRenderer(tokens) {
    return (context) => {
      return tokens.map(token => {
        switch (token.type) {
          case "text": return token.value;
          case "variable": return this._resolveVariable(token.path, context);
          case "helper": return this._executeHelper(token.name, token.args, context);
          case "computed": return this._evaluateComputed(token.expression, context);
          default: return "";
        }
      }).join("");
    };
  }

  _resolveVariable(path, context, depth = 0) {
    if (depth > this.maxDepth) return "[max depth]";
    let current = context;
    for (const key of path) {
      if (current == null) return "[undefined]";
      // Prevent prototype access
      if (key === "__proto__" || key === "constructor" || key === "prototype") return "[blocked]";
      current = current[key];
    }
    if (typeof current === "object" && current !== null) {
      return JSON.stringify(current);
    }
    return String(current ?? "[undefined]");
  }

  _executeHelper(name, argsStr, context) {
    const helper = this.helpers[name];
    if (!helper) return `[unknown helper: ${name}]`;
    const args = argsStr.split(",").map(a => {
      const trimmed = a.trim();
      if (trimmed.startsWith("'") || trimmed.startsWith('"')) {
        return trimmed.slice(1, -1);
      }
      return this._resolveVariable(trimmed.split("."), context);
    });
    return helper(...args);
  }

  _evaluateComputed(expression, context) {
    // Computed expressions allow dynamic field access patterns
    // Security: only allow property access patterns, not arbitrary code
    if (this.strictMode) {
      // In strict mode, validate expression is safe property access
      const safePattern = /^[a-zA-Z_][a-zA-Z0-9_.]*$/;
      if (!safePattern.test(expression)) {
        return "[invalid expression]";
      }
      return this._resolveVariable(expression.split("."), context);
    } else {
      // Non-strict mode: evaluate as expression for backward compatibility
      return this._unsafeEvaluate(expression, context);
    }
  }

  _unsafeEvaluate(expression, context) {
    // Legacy evaluation - restricted to context properties
    try {
      const keys = Object.keys(context);
      const values = keys.map(k => context[k]);
      const fn = new Function(...keys, `return (${expression});`);
      return String(fn(...values));
    } catch (e) {
      return `[error: ${e.message}]`;
    }
  }
}

// Audit report generator
class AuditReportGenerator extends EventEmitter {
  constructor(config = {}) {
    super();
    this.engine = new TemplateEngine({
      strictMode: config.templateStrictMode,
      maxDepth: config.maxDepth
    });
    this.reports = [];
    this.templates = new Map();
    this._registerDefaultTemplates();
  }

  _registerDefaultTemplates() {
    this.templates.set("summary", "Report: {{title}} | Generated: {{#timestamp()}} | Hash: {{#hash(title)}}");
    this.templates.set("detail", "[{{severity}}] {{message}} (source: {{source.name}}, id: {{source.id}})");
    this.templates.set("computed", "Result: {{@expression}}");
  }

  registerTemplate(name, templateStr) {
    if (typeof name !== "string" || name.length === 0) throw new Error("Invalid template name");
    if (typeof templateStr !== "string") throw new Error("Template must be a string");
    if (templateStr.length > 2048) throw new Error("Template too long");
    this.templates.set(name, templateStr);
    this.emit("template:registered", { name });
  }

  generateReport(templateName, data) {
    const templateStr = this.templates.get(templateName);
    if (!templateStr) throw new Error(`Template not found: ${templateName}`);

    // Validate data object
    if (typeof data !== "object" || data === null) throw new Error("Data must be an object");

    const renderer = this.engine.compile(templateStr);
    const output = renderer(data);

    const report = {
      id: crypto.randomUUID(),
      template: templateName,
      output,
      generatedAt: Date.now()
    };
    this.reports.push(report);
    this.emit("report:generated", report);
    return report;
  }

  getReports() {
    return [...this.reports];
  }
}

// HTTP request handler
class ReportService {
  constructor() {
    this.generator = new AuditReportGenerator({
      templateStrictMode: true,
      maxDepth: 4
    });
  }

  handleRequest(req) {
    try {
      switch (req.action) {
        case "register_template":
          return this._handleRegisterTemplate(req);
        case "generate_report":
          return this._handleGenerateReport(req);
        case "list_reports":
          return { status: 200, body: this.generator.getReports() };
        default:
          return { status: 400, body: { error: "Unknown action" } };
      }
    } catch (e) {
      return { status: 500, body: { error: e.message } };
    }
  }

  _handleRegisterTemplate(req) {
    const { name, template } = req.body || {};
    this.generator.registerTemplate(name, template);
    return { status: 201, body: { message: "Template registered", name } };
  }

  _handleGenerateReport(req) {
    const { template, data } = req.body || {};
    if (typeof template !== "string") {
      return { status: 400, body: { error: "template name required" } };
    }
    const report = this.generator.generateReport(template, data || {});
    return { status: 200, body: report };
  }

  // Admin endpoint to reconfigure the template engine
  reconfigure(config) {
    if (typeof config !== "object" || config === null) return;
    // Only allow specific config keys
    const allowed = ["templateStrictMode", "maxDepth"];
    for (const key of Object.keys(config)) {
      if (!allowed.includes(key)) continue;
      if (key === "templateStrictMode") {
        this.generator.engine.strictMode = config[key] !== false;
      }
      if (key === "maxDepth" && typeof config[key] === "number") {
        this.generator.engine.maxDepth = Math.min(Math.max(config[key], 1), 10);
      }
    }
  }
}

module.exports = { TemplateEngine, AuditReportGenerator, ReportService };
